SELECT oe.*
FROM ORIGINAL_EXAM oe
WHERE oe.semester_id = #{semesterId}

SELECT oe.exam_id, oe.course_name, oe.start_time, oe.end_time, oe.room, oe.status, oet.reason, oe.teaching_campus, oe.exam_campus, oe.teaching_dept, oe.teaching_teacher, oe.invigilation_college, oe.class_name, oe.student_count, t.name as teacher_name, oet.invigilate_role, oet.id as oet_id, s.semester_id, s.semester_name, s.year, s.is_current FROM ORIGINAL_EXAM oe INNER JOIN ORIGINAL_EXAM_TEACHER oet ON oe.exam_id = oet.exam_id INNER JOIN TEACHER t ON oet.teacher_id = t.teacher_id LEFT JOIN SEMESTER s ON oe.semester_id = s.semester_id
AND oe.course_name LIKE CONCAT('%', #{query.courseName}, '%')
AND oe.semester_id = #{query.semesterId}
AND oe.status = #{query.status}
AND oe.room LIKE CONCAT('%', #{query.room}, '%')
AND oet.teacher_id = #{query.teacherId}
AND t.name LIKE CONCAT('%', #{query.teacherName}, '%')
AND t.dept = #{query.dept}
AND oe.start_time >= #{query.startTime}
AND oe.end_time <= #{query.endTime}
ORDER BY oe.exam_id DESC, oet.invigilate_role DESC LIMIT #{query.pageSize} OFFSET ${(query.pageNum - 1) * query.pageSize}

SELECT COUNT(*)
FROM ORIGINAL_EXAM oe
INNER JOIN ORIGINAL_EXAM_TEACHER oet ON oe.exam_id = oet.exam_id
INNER JOIN TEACHER t ON oet.teacher_id = t.teacher_id

    
        AND oe.course_name LIKE CONCAT('%', #{query.courseName}, '%')
    
    
        AND oe.semester_id = #{query.semesterId}
    
    
        AND oe.status = #{query.status}
    
    
        AND oe.room LIKE CONCAT('%', #{query.room}, '%')
    
    
        AND oet.teacher_id = #{query.teacherId}
    
    
        AND t.name LIKE CONCAT('%', #{query.teacherName}, '%')
    
    
        AND t.dept = #{query.dept}
    
    
        AND oe.start_time >= #{query.startTime}
    
    
        AND oe.end_time <= #{query.endTime}

SELECT COUNT(*) AS total, SUM(CASE WHEN oet.reason IS NULL THEN 1 ELSE 0 END) AS unconfirmed, SUM(CASE WHEN oet.reason IS NOT NULL AND oet.reason = '' THEN 1 ELSE 0 END) AS noObjection, SUM(CASE WHEN oet.reason IS NOT NULL AND oet.reason != '' THEN 1 ELSE 0 END) AS hasFeedback FROM ORIGINAL_EXAM oe INNER JOIN ORIGINAL_EXAM_TEACHER oet ON oe.exam_id = oet.exam_id INNER JOIN TEACHER t ON oet.teacher_id = t.teacher_id
AND oe.semester_id = #{semesterId}
AND t.dept = #{dept}

mapper.update:
UPDATE ORIGINAL_EXAM_TEACHER
SET reason = #{reason}
WHERE id = #{id}

mapper.select:
SELECT t.teacher_id AS teacherId, t.name AS teacherName, t.dept AS dept, COUNT(*) AS total, SUM(CASE WHEN oet.reason IS NULL THEN 1 ELSE 0 END) AS unconfirmed, SUM(CASE WHEN oet.reason IS NOT NULL AND oet.reason = '' THEN 1 ELSE 0 END) AS noObjection, SUM(CASE WHEN oet.reason IS NOT NULL AND oet.reason != '' THEN 1 ELSE 0 END) AS hasFeedback FROM ORIGINAL_EXAM oe INNER JOIN ORIGINAL_EXAM_TEACHER oet ON oe.exam_id = oet.exam_id INNER JOIN TEACHER t ON oet.teacher_id = t.teacher_id
AND oe.semester_id = #{semesterId}
AND t.dept = #{dept}
GROUP BY t.teacher_id, t.name, t.dept ORDER BY unconfirmed DESC, t.name
